const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_DIVISOR = 10; // 10 %, as an exact fraction

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const quote = scenario.steps[0] as QuoteStep;
  const basePremium = quote.items.length === 0 ? 0 : 100;
  const firstInsuranceSurcharge =
    basePremium / FIRST_INSURANCE_SURCHARGE_DIVISOR;
  const premium = basePremium + firstInsuranceSurcharge + PROCESSING_FEE;
  return { results: [{ premium: Math.ceil(premium) }] };
};
